"""Verify eight Hail role updates and one bounded tool integration, preserving all earlier source and scientific checks."""
import gzip,json
from setup_deseq2_reference import ROOT,pin
from signac_scan_evidence import unpack,byte_pin
from catalog_source_integrity import verify_source,ALLOWED_PATHS
from catalog_fixed_cohort import verify_fixed_cohort
from hail_catalog import verify_review_extension,historical_readme_document,hail_metadata,load_catalog_registry

def verify():
    data=ROOT/'docs/literature/omics-2023-2026';proof=json.loads((data/'hail-catalog-validation.json').read_bytes());assert proof['status']=='passed-eight-Hail-primary-roles-and-one-scoped-integration' and (proof['new_scoped_integrations'],proof['including_existing_adapters'],proof['missing_integrations'],proof['prior_reviews_preserved'],proof['reviewed_uses'],proof['supporting_pointers'])==(83,86,248,952,960,331) and proof['whole_goal_complete'] is False and proof['whole_paper_reproduced'] is False and proof['website_deployed'] is False;assert pin(data/'hail-catalog-support.zip')==proof['archive'];files=unpack(data/'hail-catalog-support.zip',proof)
    for name,want in proof['source_pins'].items():assert pin(ROOT/name)==byte_pin(files['current-source/'+name])==want,name
    for name,want in proof['parent_proofs'].items():assert pin(ROOT/name)==want
    parent=json.loads((data/'biomart-catalog-validation.json').read_bytes());assert pin(data/'biomart-catalog-support.zip')==parent['archive'];old=unpack(data/'biomart-catalog-support.zip',parent)
    for name,want in parent['source_pins'].items():
        assert byte_pin(old['current-source/'+name])==want
        if name=='README.md':historical_readme_document(ROOT,data,old['current-source/'+name],want)
        else:verify_source(ROOT,data,name,want['sha256'])
    assert ALLOWED_PATHS==frozenset({'.gitattributes','src/main/java/org/jlinalg/cli/JLinAlgCli.java','tools/literature/render_review.py','tools/literature/reviewed-uses.json','tools/literature/repeat_catalog.py','tools/literature/check_review_ui.cjs','tools/literature/check_repeat_review_ui.cjs'})
    for name in ['papers.json','tool-inventory.json','summary.json','catalog.md','implementation-plan.md','README.md','WARNINGS.md','hail-role-coverage.json','hail-prior-reviews.json.gz','hail-prior-papers.json.gz','hail-reviews-shared-source-compatibility.json','hail-render-shared-source-compatibility.json','hail-root-readme-evolution.json','hail-source-audit.json']:assert files['catalog-snapshot/'+name]==(data/name).read_bytes(),name
    for name in ['literature-review.html','literature-warnings.html']:assert files['site-snapshot/'+name]==(ROOT/'site'/name).read_bytes()
    assert files['catalog-snapshot/reviewed-uses.json']==(ROOT/'tools/literature/reviewed-uses.json').read_bytes();assert old['catalog-snapshot/reviewed-uses.json']==gzip.decompress((data/'hail-prior-reviews.json.gz').read_bytes()) and old['catalog-snapshot/papers.json']==gzip.decompress((data/'hail-prior-papers.json.gz').read_bytes());papers=json.loads((data/'papers.json').read_bytes());verify_fixed_cohort(ROOT,data,papers);reviews=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes())['reviews'];verify_review_extension(ROOT,data,reviews);assert len(papers)==250 and len(reviews)==960 and sum(len(p['tools']) for p in papers)==2450
    changed=[]
    for before,current in zip(json.loads(old['catalog-snapshot/papers.json']),papers):
        assert {k:v for k,v in before.items() if k!='tools'}=={k:v for k,v in current.items() if k!='tools'} and [t for t in before['tools'] if t['tool_id']!='hail']==[t for t in current['tools'] if t['tool_id']!='hail']
        if before!=current:changed.append(current['paper_id'])
    assert changed==['P055','P168','P186','P191','P204','P210','P220','P246'];before={t['id']:t for t in json.loads(old['catalog-snapshot/tool-inventory.json'])};current={t['id']:t for t in json.loads((data/'tool-inventory.json').read_bytes())};assert len(before)==len(current)==390 and {n for n in before if before[n]!=current[n]}=={'hail'} and before['hail']['implementation_status']=='missing';metadata=hail_metadata(ROOT,data);assert all(current['hail'][k]==v for k,v in metadata.items()) and current['hail']['paper_count']==8;counts=json.loads((data/'summary.json').read_bytes())['implementation_status_counts'];assert (counts['native-subset-validated'],counts['upstream-adapter-validated'],counts['missing'])==(17,66,248);registry=load_catalog_registry(ROOT);assert len(registry)==len({r['id'] for r in registry})==428
    audit=json.loads((data/'hail-source-audit.json').read_bytes());assert audit['status']=='passed-250-current-primary-source-and-960-role-audit' and (audit['source_XML_hashes_verified'],audit['fulltext_DOIs_verified'],audit['observations_verified'],audit['reviewed_uses_verified'],audit['supporting_pointers_verified'])==(250,250,2450,960,331) and audit['changed_paper_roles']==changed and audit['prior_reviews_preserved']==952
    get=lambda name:json.loads(files['build/literature-review/hail-runtime/'+name]);gates=get('catalog-scientific-gates-1/COMPLETED.json');assert gates['status']=='passed-Hail-and-all-eleven-inherited-scientific-component-gates' and len(gates['checks'])==proof['scientific_gates']==12 and gates['frozen_scientific_sources_or_verifiers_changed'] is False
    for name,want in gates['source_pins'].items():assert pin(ROOT/name)==want
    ui=get('catalog-ui-2/COMPLETED.json');assert ui['page']==pin(ROOT/'site/literature-review.html') and ui['warning_page']==pin(ROOT/'site/literature-warnings.html') and ui['remote_mutations'] is False;general=get('catalog-ui-2/general/ui-validation.json');focused=get('catalog-ui-2/hail/hail-ui-verification.json');assert general['status']==focused['status']=='passed' and len(general['checks'])==proof['general_browser_checks']==299 and len(focused['checks'])==proof['focused_browser_checks']==5 and focused['document_width']<=390 and not focused['page_errors']
    reuse=ui['reused_general'];assert reuse['same_page_bytes'] is True and reuse['source']=='build/literature-review/hail-runtime/catalog-ui-1';original_general=get('catalog-ui-1/GENERAL-COMPLETED.json');assert original_general['status']=='passed-general-only-from-retained-failed-focused-run' and original_general['focused_run_passed'] is False and original_general['page']==ui['page'] and original_general['warning_page']==ui['warning_page'] and byte_pin(files[reuse['completion_path']])==reuse['completion'];assert files['build/literature-review/hail-runtime/catalog-ui-1/general/ui-validation.json']==files['build/literature-review/hail-runtime/catalog-ui-2/general/ui-validation.json'] and get('catalog-ui-1/general.process.json')['exit_code']==0 and get('catalog-ui-1/hail.process.json')['exit_code']==1
    for name,want in original_general['source_pins'].items():assert pin(ROOT/name)==want and byte_pin(files['build/literature-review/hail-runtime/catalog-ui-1/source-snapshot/'+name])==want
    for name,want in [*ui['source_pins'].items(),*ui['input_pins'].items()]:assert pin(ROOT/name)==want
    lines=(data/'SHA256SUMS').read_text(encoding='utf8').splitlines();manifest={r.split('  ',1)[1]:r.split('  ',1)[0] for r in lines};assert len(lines)==len(manifest) and set(manifest)=={p.name for p in data.iterdir() if p.is_file() and p.name!='SHA256SUMS'} and all(pin(data/n)['sha256']==want for n,want in manifest.items()) and b'\r\n' not in (data/'SHA256SUMS').read_bytes();assert pin(ROOT/'build/cli/omicsmatic-0.3.7.jar')==proof['canonical_executable_unchanged'] and 'ignore_patterns("literature-review.html", "literature-warnings.html")' in (ROOT/'.github/workflows/pages.yml').read_text(encoding='utf8');print('Verified250 papers/2450 observations/960 reviews;83 new scoped integrations/86 including existing;248 missing;12 scientific/component gates and304 browser checks. Full goal remains open.');return proof

if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable exact catalog checks')
    verify()
